const $=s=>document.querySelector(s), money=n=>'UGX '+n.toLocaleString('en-UG');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(p,w=800)=>`https://images.unsplash.com/${p.photo}?auto=format&fit=crop&w=${w}&q=80`;
let saved=[];try{saved=JSON.parse(localStorage.getItem('ob-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}let onlySaved=false;
function matches(p,f){return (!f.location||`${p.city} ${p.area} ${p.title}`.toLowerCase().includes(f.location.trim().toLowerCase()))&&(!f.budget||p.rent<=Number(f.budget))&&(!f.beds||(Number(f.beds)===3?p.beds>=3:p.beds===Number(f.beds)))}
function render(){const f=Object.fromEntries(new FormData($('#search')));let items=listings.filter(p=>matches(p,f)&&(!onlySaved||saved.includes(p.id)));if($('#sort').value==='low')items.sort((a,b)=>a.rent-b.rent);if($('#sort').value==='high')items.sort((a,b)=>b.rent-a.rent);$('#grid').innerHTML=items.map(p=>`<article class="card"><div class="card-photo"><a href="#property/${p.id}" aria-label="View ${esc(p.title)}"><img loading="lazy" src="${photo(p)}" alt="Illustrative ${esc(p.type.toLowerCase())} interior or exterior"></a><span class="type">${esc(p.type)}${p.example?" · Example":""}</span><button class="save" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button></div><div class="card-body"><p class="location">⌖ ${esc(p.area)}, ${esc(p.city)}</p><h3><a href="#property/${p.id}">${esc(p.title)}</a></h3><div class="features">${p.beds} bed${p.beds>1?'s':''} &nbsp; · &nbsp; ${p.baths} bath${p.baths>1?'s':''} &nbsp; · &nbsp; ${p.size} m²</div><div class="price-row"><span class="price">${money(p.rent)} <small>/ month</small></span><a class="view" href="#property/${p.id}" aria-label="View ${esc(p.title)}">↗</a></div></div></article>`).join('');$('#empty').hidden=items.length>0;$('#resultCount').textContent=`${items.length} ${onlySaved?'saved ':''}home${items.length===1?'':'s'} to explore`;$('#savedCount').textContent=saved.length;$('#savedNav').setAttribute('aria-pressed',String(onlySaved));}
function reset(){onlySaved=false;$('#search').reset();$('#sort').value='recommended';render()}
$('#search').addEventListener('submit',e=>{e.preventDefault();render()});$('#search').addEventListener('change',render);$('#search input').addEventListener('input',render);$('#sort').addEventListener('change',render);$('#clear').onclick=reset;$('#emptyReset').onclick=reset;$('#savedNav').onclick=()=>{onlySaved=!onlySaved;render();$('#homes').scrollIntoView()};
$('#grid').addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(!b)return;const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('ob-saved',JSON.stringify(saved))}catch{toast('Browser storage unavailable; saves last for this visit.')}render()});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function contactLinks(p,message){const links=[];if(p.phone&&/^\+[1-9]\d{7,14}$/.test(p.phone)){links.push(`<a class="primary" target="_blank" rel="noopener noreferrer" href="https://wa.me/${p.phone.slice(1)}?text=${encodeURIComponent(message)}">Open WhatsApp ↗</a>`,`<a href="tel:${p.phone}">Call ${esc(p.phone)}</a>`)}if(p.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))links.push(`<a class="primary" href="mailto:${encodeURIComponent(p.email)}?subject=${encodeURIComponent('Rental enquiry: '+p.title)}&body=${encodeURIComponent(message)}">Open email app ↗</a>`);return links.join('')}
function route(){const id=location.hash.startsWith('#property/')?location.hash.slice(10):null;const p=listings.find(p=>p.id===id);if(!id){if($('#detail').open)$('#detail').close();return}if(!p){toast('This home could not be found.');history.replaceState(null,'','#homes');return}const hasContact=!p.example&&!!contactLinks(p,'Hello');$('#detailContent').innerHTML=`<img class="detail-image" src="${photo(p,1400)}" alt="Illustrative property photograph"><div class="detail-body"><p class="eyebrow">${p.example?'EXAMPLE LISTING · ILLUSTRATIVE PHOTO':esc(p.type.toUpperCase())}</p><p>${esc(p.area)}, ${esc(p.city)}, Uganda</p><h2>${esc(p.title)}</h2><div class="detail-columns"><div><div class="facts"><span>${p.beds} bedrooms</span><span>${p.baths} bathrooms</span><span>${p.size} m²</span></div><h3>About this home</h3><p>${esc(p.description)}</p><h3>What’s included</h3><div class="facts">${p.amenities.map(x=>`<span>✓ ${esc(x)}</span>`).join('')}</div><h3>Tenancy details</h3><p>Monthly rent: <strong>${money(p.rent)}</strong><br>Rent in advance: ${esc(p.advance)}<br>Deposit and utility costs: confirm with owner<br>Availability: ${p.example?'example only; not available to book':'confirm with owner'}</p><h3>Before you commit</h3><p>Visit the property, confirm who owns or manages it, and agree all costs in writing before making a payment.</p><button class="text-button" id="share">Copy property link ↗</button></div><aside class="contact-box"><span class="price">${money(p.rent)} <small>/ month</small></span><h3>Contact ${esc(p.owner)}</h3>${hasContact?`<form id="enquiry"><label>Your name<input name="name" required maxlength="80" autocomplete="name"></label><label>Your message<textarea name="message" required maxlength="1500" rows="4">Hello, I’m interested in ${esc(p.title)} in ${esc(p.area)}. Is it available, and can we arrange a viewing?</textarea></label><button class="primary">Prepare enquiry ↗</button></form><div id="contactActions"></div><small>Your message opens in your messaging app. Review and send it there; this site does not send or store enquiries.</small>`:`<p>This is an example home. Owner contact is unavailable.</p><small>Live listings will offer direct WhatsApp, phone or email contact once an owner provides their details. No enquiry will be sent from this example.</small>`}</aside></div></div>`;if(!$('#detail').open)$('#detail').showModal();$('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Property link copied')}catch{toast('Copy the address from your browser to share this home.')}};if(hasContact)$('#enquiry').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);$('#contactActions').innerHTML=contactLinks(p,`${f.get('message')}\n\nFrom: ${f.get('name')}\nProperty: ${location.href}`)}}
for(const d of document.querySelectorAll('dialog')){d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}$('#detail').addEventListener('close',()=>{if(location.hash.startsWith('#property/'))history.replaceState(null,'','#homes')});
$('#listingGuide').onclick=()=>{$('#infoContent').innerHTML='<p class="eyebrow">OWNER LISTING CHECKLIST</p><h2>Bring your home online.</h2><ol><li>Provide the neighbourhood, town and property type.</li><li>Confirm monthly rent in UGX, deposit, advance payment and availability.</li><li>Add bedroom and bathroom counts, amenities and accurate photos you have permission to use.</li><li>Provide your name and an approved phone number or email for direct enquiries.</li><li>Send these details to the site operator for review and publication.</li></ol><p>Online self-service listing submission is not available in this first version.</p>';$('#info').showModal()};$('#safety').onclick=()=>{$('#infoContent').innerHTML='<h2>Rent with care.</h2><ul><li>View the property in person before paying.</li><li>Confirm the identity and authority of the owner or agent.</li><li>Ask about water, electricity, security, deposits and all additional charges.</li><li>Agree the rent and tenancy terms in writing and request receipts.</li><li>Be cautious of pressure to pay before viewing.</li></ul>';$('#info').showModal()};window.addEventListener('hashchange',route);render();route();

